export function permissions(role) {
  const list = [];

  switch (role) {
    case "admin":
      list.push("delete");
      break;
    case "editor":
      list.push("write");
      break;
    case "viewer":
      list.push("read");
      break;
    default:
      list.push("none");
  }

  return list;
}
